        r1 = routes[i][:a] + routes[i][a + 1:]
        r2 = routes[j][:]
        if i < j:
            r2.insert(pos, node)
        else:
            r2.insert(pos, node)
        routes[i] = r1
        routes[j] = r2
        return True

    def try_swap(routes):
        best = None
        rcount = len(routes)
        for i in range(rcount):
            r1 = routes[i]
            l1 = len(r1)
            for j in range(i + 1, rcount):
                r2 = routes[j]
                l2 = len(r2)
                load1 = route_load(r1)
                load2 = route_load(r2)
                for a in range(l1):
                    n1 = r1[a]
                    p1 = depot if a == 0 else r1[a - 1]
                    q1 = depot if a == l1 - 1 else r1[a + 1]
                    rem1 = dist[p1][q1] - dist[p1][n1] - dist[n1][q1]
                    add1_base = load1 - demands[n1] + demands[n1]
                    for b in range(l2):
                        n2 = r2[b]
                        p2 = depot if b == 0 else r2[b - 1]
                        q2 = depot if b == l2 - 1 else r2[b + 1]
                        rem2 = dist[p2][q2] - dist[p2][n2] - dist[n2][q2]
                        if load1 - demands[n1] + demands[n2] > capacity:
                            continue
                        if load2 - demands[n2] + demands[n1] > capacity:
                            continue
                        add1 = dist[p1][n2] + dist[n2][q1] - dist[p1][n1] - dist[n1][q1]
                        add2 = dist[p2][n1] + dist[n1][q2] - dist[p2][n2] - dist[n2][q2]
                        delta = add1 + add2
                        if delta < 0:
                            key = (delta, i, a, j, b, n1, n2)
                            if best is None or key < best[0]:
                                best = (key, i, a, j, b)
        if best is None:
            return False
        _, i, a, j, b = best
        r1 = routes[i][:]
        r2 = routes[j][:]
        r1[a], r2[b] = r2[b], r1[a]
        routes[i] = r1
        routes[j] = r2
        return True

    passes = 0
    improved = True
    while improved and passes < 80:
        passes += 1
        improved = False

        # Merge if beneficial
        best_merge = None
        for i in range(len(routes)):
            for j in range(i + 1, len(routes)):
                m = merge_routes(routes[i], routes[j])
                if m is not None:
                    delta = route_cost(m) - route_cost(routes[i]) - route_cost(routes[j])
                    key = (delta, i, j, tuple(m))
                    if best_merge is None or key < best_merge[0]:
                        best_merge = (key, i, j, m)
        if best_merge is not None:
            _, i, j, m = best_merge
            routes[i] = m
            routes.pop(j)
            improved = True
            continue

        if try_relocate(routes):
            improved = True
            for k in range(len(routes)):
                routes[k] = route_two_opt(routes[k])
            routes = normalize(routes)
            continue

        if try_swap(routes):
            improved = True
            for k in range(len(routes)):
                routes[k] = route_two_opt(routes[k])
            routes = normalize(routes)
            continue

        # Intra-route cleanup
        changed = False
        for k in range(len(routes)):
            nr = route_two_opt(routes[k])
            if route_cost(nr) < route_cost(routes[k]):
                routes[k] = nr
                changed = True
        if changed:
            improved = True
            routes = normalize(routes)

    # Final deterministic repair: ensure all customers exactly once.
    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = [c for c in customers if c not in seen]
    if missing:
        # remove duplicates if any, then insert missing greedily
        for c in list(seen.keys()):
            while seen.get(c, 0) > 1:
                for r in routes:
                    if c in r:
                        r.remove(c)
                        seen[c] -= 1
                        break
        for c in missing:
            best = None
            for i, r in enumerate(routes):
                if route_load(r) + demands[c] > capacity:
                    continue
                pos, delta = best_insertion(r, c)
                key = (delta, i, pos, c)
                if best is None or key < best[0]:
                    best = (key, i, pos)
            if best is None:
                routes.append([c])
            else:
                _, i, pos = best
                routes[i].insert(pos, c)

    routes = normalize(routes)
    for i in range(len(routes)):
        routes[i] = route_two_opt(routes[i])

    return routes
